pub struct ProcessorRegsInfo {
    pub names: &'static [&'static str],
    pub segment_registers: std::ops::Range<usize>,
    pub data_segment_register: usize,
    pub code_segment_register: usize,
}
impl ProcessorRegsInfo {
    pub const fn name_from_idx(&self, idx: usize) -> Option<&'static str> {
        if idx >= self.names.len() {
            return None;
        }
        Some(self.names[idx])
    }
    pub fn segment_register_names(&self) -> &'static [&'static str] {
        &self.names[self.segment_registers.clone()]
    }
    pub const fn is_segment_register(&self, idx: usize) -> bool {
        idx >= self.segment_registers.start && idx < self.segment_registers.end
    }
    pub const fn is_data_segment(&self, idx: usize) -> bool {
        idx == self.data_segment_register
    }
    pub const fn is_code_segment(&self, idx: usize) -> bool {
        idx == self.code_segment_register
    }
}
pub trait ProcessorRegsHaveInfo {
    const INFO: Option<ProcessorRegsInfo> = None;
}
pub trait ProcessorWithRegsInfo:
    Copy + TryFromPrimitive<Primitive = usize> + Into<usize>
{
    const NAMES: &[&str];
    const SEGMENT_REGISTERS_START: usize;
    const SEGMENT_REGISTERS_END: usize;
    const DATA_SEGMENT_REGISTER: usize;
    const CODE_SEGMENT_REGISTER: usize;
    fn name(self) -> &'static str {
        Self::NAMES[self.into()]
    }
    fn is_segment_register(self) -> bool {
        self.into() >= Self::SEGMENT_REGISTERS_START
            && self.into() < Self::SEGMENT_REGISTERS_END
    }
    fn is_data_segment(self) -> bool {
        self.into() == Self::DATA_SEGMENT_REGISTER
    }
    fn is_code_segment(self) -> bool {
        self.into() == Self::CODE_SEGMENT_REGISTER
    }
}
impl<P: ProcessorWithRegsInfo> ProcessorRegsHaveInfo for P {
    const INFO: Option<ProcessorRegsInfo> = Some(ProcessorRegsInfo {
        names: P::NAMES,
        segment_registers: P::SEGMENT_REGISTERS_START..P::SEGMENT_REGISTERS_END,
        data_segment_register: P::DATA_SEGMENT_REGISTER,
        code_segment_register: P::CODE_SEGMENT_REGISTER,
    });
}
