#[derive(
    Debug, Clone, Copy, PartialEq, Eq, Hash, TryFromPrimitive, IntoPrimitive,
)]
#[repr(usize)]
pub enum WasmReg {
    Cs = 0usize,
    Ds = 1usize,
}
impl ProcessorWithRegsInfo for WasmReg {
    const NAMES: &[&str] = &["CS", "DS"];
    const SEGMENT_REGISTERS_START: usize = 0usize;
    const SEGMENT_REGISTERS_END: usize = 2usize;
    const DATA_SEGMENT_REGISTER: usize = 1usize;
    const CODE_SEGMENT_REGISTER: usize = 0usize;
}
